package in.guvi.fraud.web;
import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.*;
@WebServlet("/login") public class AuthServlet extends HttpServlet{protected void doGet(HttpServletRequest q,HttpServletResponse p)throws IOException,ServletException{q.getRequestDispatcher("/login.jsp").forward(q,p);}protected void doPost(HttpServletRequest q,HttpServletResponse p)throws IOException,ServletException{String u=q.getParameter("username"),pw=q.getParameter("password"),r=q.getParameter("role");boolean ok=("admin".equals(u)&&"admin123".equals(pw)&&"admin".equals(r))||("user".equals(u)&&"user123".equals(pw)&&"user".equals(r));if(ok){q.getSession(true).setAttribute("role",r);p.sendRedirect(q.getContextPath()+(r.equals("admin")?"/admin":"/user"));}else{q.setAttribute("error","Invalid demo credentials or role.");q.getRequestDispatcher("/login.jsp").forward(q,p);}}}
